let vaccinationTab='dashboard';
let vaccinationData=null,vaccinationRole=null,vaccinationDueActions=[];
let vaccinationEditingScheduleId=null,vaccinationEditingBatchId=null,vaccinationOverrideTarget=null;
let vaccinationFilters={search:'',scheduleId:'',ageMin:'',ageMax:'',from:'',to:'',status:''};
const vaccinationTemplates=[['PPR','Peste des petits ruminants'],['FMD','Foot-and-mouth disease'],['ET','Enterotoxaemia'],['HS','Haemorrhagic septicaemia'],['Goat Pox','Goat pox'],['Anthrax','Anthrax'],['ORF','Contagious ecthyma (ORF)']];
const vaccineTabNames=['dashboard','schedule','record','upcoming','overdue','completed','history','inventory','reports','settings'];
function vaccinationText(key){return (vaccinationFormLabels[lang]&&vaccinationFormLabels[lang][key])||(vaccinationLabels[lang]&&vaccinationLabels[lang][key])||(vaccinationExtraLabels[lang]&&vaccinationExtraLabels[lang][key])||vaccinationFormLabels.en[key]||vaccinationLabels.en[key]||vaccinationExtraLabels.en[key]||key}
function setVaccinationTab(tab){vaccinationTab=tab;if(currentPage!=='vaccination'){goPage('vaccination');return}if(!vaccinationData)return;renderVaccinationContent(document.getElementById('view'),renderVersion)}
async function vaccinationFetchRows(table,farmId){let rows=[],start=0;while(true){const {data,error}=await sb.from(table).select('*').eq('farm_id',farmId).order('created_at',{ascending:false}).range(start,start+499);if(error)throw error;rows.push(...(data||[]));if(!data||data.length<500)return rows;start+=500}}
function vaccinationEscape(value){return value===null||value===undefined||value===''?'—':esc(value)}
function vaccinationTable(headers,rows){if(!rows.length)return `<p class="muted">${vaccinationText('noRows')}</p>`;return `<div class="tablewrap"><table><thead><tr>${headers.map(header=>`<th>${esc(header)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(cell=>`<td>${cell}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
async function renderVaccinationPage(view,version){
  view.innerHTML=`<div class="vax-tabs" role="tablist">${vaccineTabNames.map(tab=>`<button role="tab" aria-selected="${vaccinationTab===tab}" class="${vaccinationTab===tab?'on':''}" onclick="setVaccinationTab('${tab}')">${vaccinationText(tab)}</button>`).join('')}</div><div id="vaccinationContent"><p class="muted">${vaccinationText('loading')}</p></div>`;
  try{
    const {data:member,error:memberError}=await sb.from('farm_members').select('farm_id,role').eq('user_id',currentUser.id).limit(1).maybeSingle();
    if(memberError)throw memberError;if(!member)throw new Error(vaccinationText('notInstalled'));
    vaccinationRole=member.role;
    const [schedules,goats,records,inventory,overrides,legacyHealth]=await Promise.all(['vaccination_schedules','goats','vaccination_records','vaccination_inventory','vaccination_due_overrides','health_records'].map(table=>vaccinationFetchRows(table,member.farm_id)));
    if(version!==renderVersion||currentPage!=='vaccination')return;
    vaccinationData={farmId:member.farm_id,schedules,goats,records,inventory,overrides,legacyHealth};
    renderVaccinationContent(view,version);
  }catch(error){
    if(version!==renderVersion)return;
    const target=view.querySelector('#vaccinationContent');if(!target)return;
    view.querySelectorAll('.vax-tabs button').forEach(button=>button.disabled=true);
    target.innerHTML=`<div class="notice">${error.code==='42P01'||error.code==='PGRST205'?vaccinationText('notInstalled'):esc(error.message)}</div>`;
  }
}
function renderVaccinationContent(view,version){
  if(version!==renderVersion||currentPage!=='vaccination'||!vaccinationData)return;
  const target=view.querySelector('#vaccinationContent');if(!target)return;
  view.querySelectorAll('.vax-tabs button').forEach((button,index)=>{button.classList.toggle('on',vaccineTabNames[index]===vaccinationTab);button.setAttribute('aria-selected',String(vaccineTabNames[index]===vaccinationTab))});
  if(vaccinationTab==='dashboard')target.innerHTML=vaccinationDashboard();
  else if(vaccinationTab==='schedule'||vaccinationTab==='settings')target.innerHTML=vaccinationSchedulePage(vaccinationTab==='settings');
  else if(vaccinationTab==='record')target.innerHTML=vaccinationRecordPage();
  else if(vaccinationTab==='upcoming')target.innerHTML=vaccinationDuePage('upcoming');
  else if(vaccinationTab==='overdue')target.innerHTML=vaccinationDuePage('overdue');
  else if(vaccinationTab==='completed')target.innerHTML=vaccinationDuePage('completed');
  else if(vaccinationTab==='history')target.innerHTML=vaccinationHistoryPage();
  else if(vaccinationTab==='inventory')target.innerHTML=vaccinationInventoryPage();
  else target.innerHTML=vaccinationReportsPage();
  const recordForm=target.querySelector('#vaccinationRecordForm');if(recordForm)for(const field of ['goat_id','vaccination_schedule_id','vaccination_date'])recordForm.elements[field].addEventListener('change',updateVaccinationNextDue);
  const scheduleForm=target.querySelector('#vaccinationScheduleForm');if(scheduleForm)scheduleForm.elements.vaccine_name.addEventListener('change',()=>{const template=vaccinationTemplates.find(item=>item[0]===scheduleForm.elements.vaccine_name.value);if(template&&!vaccinationEditingScheduleId)scheduleForm.elements.disease.value=template[1]});
}
function vaccinationDashboard(){
  const today=new Date().toISOString().slice(0,10),soon=addCalendarDays(today,7),expiring=addCalendarDays(today,30);
  const due=vaccinationDueItems(),cards=[[vaccinationText('activeGoats'),vaccinationData.goats.filter(goat=>goat.status==='Active').length],[vaccinationText('dueToday'),due.filter(item=>item.status==='today').length],[vaccinationText('dueSeven'),due.filter(item=>item.status==='upcoming'&&item.date<=soon).length],[vaccinationText('overdueCount'),due.filter(item=>item.status==='overdue').length],[vaccinationText('boosters'),due.filter(item=>item.booster&&item.date>=today&&item.date<=expiring).length],[vaccinationText('expiring'),vaccinationData.inventory.filter(batch=>batch.expiry_date>=today&&batch.expiry_date<=expiring&&Number(batch.quantity_remaining)>0).length],[vaccinationText('lowStock'),vaccinationData.inventory.filter(batch=>Number(batch.quantity_remaining)<=Number(batch.low_stock_threshold)).length],[vaccinationText('reviews'),due.filter(item=>item.status==='review').length]];
  const reminders=due.filter(item=>['today','upcoming','overdue','review'].includes(item.status)).sort((a,b)=>(a.date||'9999-12-31').localeCompare(b.date||'9999-12-31')).slice(0,8);
  return `<div class="grid vax-stats">${cards.map(([label,value])=>`<article class="stat"><span class="stat-label">${esc(label)}</span><strong>${value}</strong></article>`).join('')}</div><div class="notice">${vaccinationText('clinicalNotice')} ${vaccinationText('reminderNotice')}</div><section class="panel"><h3>${vaccinationText('quickActions')}</h3><div class="quick-actions"><button onclick="setVaccinationTab('record')">${vaccinationText('recordVaccine')}</button><button class="secondary" onclick="setVaccinationTab('upcoming')">${vaccinationText('upcoming')}</button><button class="secondary" onclick="setVaccinationTab('inventory')">${vaccinationText('inventory')}</button></div></section><section class="panel"><h3>${vaccinationText('recent')}</h3>${vaccinationTable([vaccinationText('goat'),vaccinationText('vaccine'),vaccinationText('date'),vaccinationText('dose'),vaccinationText('batch')],vaccinationData.records.slice(0,8).map(record=>[vaccinationEscape(record.goat_id),vaccinationEscape(record.vaccine_name_snapshot),vaccinationEscape(record.vaccination_date),String(record.dose_number),vaccinationEscape(record.batch_number)]))}</section><section class="panel"><h3>${vaccinationText('reminders')}</h3>${vaccinationDueTable(reminders)}</section>`;
}
function vaccinationDueTable(items){return vaccinationTable([vaccinationText('goat'),vaccinationText('vaccine'),vaccinationText('dose'),vaccinationText('dueDate'),vaccinationText('status')],items.map(item=>[vaccinationEscape(item.goat?.goat_id),vaccinationEscape(item.schedule.vaccine_name),item.dose??'—',vaccinationEscape(item.date),vaccinationText(item.status+'Status')]))}
function vaccinationLegacyMatches(record,schedule){const vaccine=schedule.vaccine_name.toLowerCase(),type=String(record.record_type||'').toLowerCase(),item=String(record.item_name||'').toLowerCase();return type==='vaccination'||type===vaccine||item.includes(vaccine)}
function vaccinationDueItems(){
  const today=new Date().toISOString().slice(0,10),items=[];
  for(const schedule of vaccinationData.schedules.filter(row=>row.active&&row.veterinarian_confirmed))for(const goat of vaccinationData.goats.filter(row=>row.status==='Active')){
    const history=vaccinationData.records.filter(row=>row.goat_id===goat.goat_id&&row.vaccination_schedule_id===schedule.id).sort((a,b)=>Number(a.dose_number)-Number(b.dose_number)),last=history.at(-1)||null,dose=last?Number(last.dose_number)+1:1;
    let date=null,status='completed',reason='';
    const legacyHistory=!last&&vaccinationData.legacyHealth.some(record=>record.goat_id===goat.goat_id&&record.record_date<=today&&vaccinationLegacyMatches(record,schedule));
    if(legacyHistory){status='review';reason=vaccinationText('legacyReview')}
    else if(!goat.date_of_birth){status='review';reason=vaccinationText('noDob')}
    else if(schedule.maternal_status_rule&&goat.maternal_vaccination_status==='Unknown'){status='review';reason=vaccinationText('reviewStatus')}
    else if(!last){date=addCalendarDays(goat.date_of_birth,schedule.minimum_age_days);if(date&&date<today){status='review';reason=vaccinationText('missed')}}
    else date=last.next_due_date||vaccinationNextDate(schedule,Number(last.dose_number),last.vaccination_date);
    const requiresReview=status==='review';
    const override=vaccinationData.overrides.filter(row=>row.goat_id===goat.goat_id&&row.vaccination_schedule_id===schedule.id&&Number(row.dose_number)===dose).sort((a,b)=>b.created_at.localeCompare(a.created_at))[0];if(override)date=override.new_due_date;
    if(requiresReview)status='review';
    else if(status!=='review'&&last&&Number(last.dose_number)<Number(schedule.primary_dose_count)&&date&&date<today){status='review';reason=vaccinationText('missed')}
    else if(date)status=date<today?'overdue':date===today?'today':'upcoming';
    if(status==='review'&&!reason)reason=vaccinationText('reviewStatus');
    items.push({schedule,goat,last,dose,date,status,reason,booster:!!last&&Number(last.dose_number)>=Number(schedule.primary_dose_count)});
  }
  return items;
}
function addCalendarDays(date,days){if(!date||!Number.isInteger(Number(days)))return null;const value=new Date(`${date}T00:00:00Z`);if(Number.isNaN(value.getTime()))return null;value.setUTCDate(value.getUTCDate()+Number(days));return value.toISOString().slice(0,10)}
function vaccinationNextDate(schedule,dose,date){const count=Number(schedule.primary_dose_count);if(!count)return null;if(dose<count)return schedule.primary_dose_interval_days?addCalendarDays(date,schedule.primary_dose_interval_days):null;if(dose===count){const interval=schedule.booster_interval_days||schedule.recurring_interval_days;return interval?addCalendarDays(date,interval):null}const interval=schedule.recurring_interval_days||schedule.booster_interval_days;return interval?addCalendarDays(date,interval):null}
function vaccinationIsManager(){return ['owner','manager'].includes(vaccinationRole)}
function vaccinationCanRecord(){return ['owner','manager','staff'].includes(vaccinationRole)}
function vaccineAgeDays(goat,date=new Date().toISOString().slice(0,10)){if(!goat?.date_of_birth)return null;const birth=new Date(`${goat.date_of_birth}T00:00:00Z`),current=new Date(`${date}T00:00:00Z`);return Number.isNaN(birth.getTime())||Number.isNaN(current.getTime())?null:Math.floor((current-birth)/86400000)}
function vaccineInput(name,label,value='',type='text',attrs=''){return `<label>${vaccinationText(label)}<input name="${name}" type="${type}" value="${esc(value??'')}" ${attrs}></label>`}
function vaccineArea(name,label,value=''){return `<label class="vax-wide">${vaccinationText(label)}<textarea name="${name}">${esc(value||'')}</textarea></label>`}
function vaccineSelect(name,label,options,value='',attrs=''){return `<label>${vaccinationText(label)}<select name="${name}" ${attrs}>${options.map(item=>`<option value="${esc(item.value)}" ${String(value)===String(item.value)?'selected':''}>${esc(item.label)}</option>`).join('')}</select></label>`}
function vaccinationSchedulePage(settings){
  const rows=vaccinationData.schedules.map(item=>[esc(item.vaccine_name),esc(item.disease),item.minimum_age_days??'—',item.primary_dose_count??'—',item.primary_dose_interval_days??'—',item.booster_interval_days??'—',item.recurring_interval_days??'—',vaccinationEscape(item.product_name),item.active&&item.veterinarian_confirmed?vaccinationText('completedStatus'):vaccinationText('reviewStatus'),vaccinationIsManager()?`<button class="small secondary" onclick="editVaccinationSchedule('${item.id}')">${vaccinationText('edit')}</button>`:'—']);
  return `<div class="notice">${vaccinationText('clinicalNotice')}</div><section class="panel"><div class="row vax-heading"><h3>${vaccinationText(settings?'settings':'schedule')}</h3>${settings&&vaccinationIsManager()?`<button onclick="newVaccinationSchedule()">${vaccinationText('newSchedule')}</button><button class="secondary" onclick="addVaccinationTemplates()">${vaccinationText('addTemplates')}</button>`:''}</div>${vaccinationTable([vaccinationText('vaccine'),vaccinationText('disease'),vaccinationText('minAge'),vaccinationText('primaryCount'),vaccinationText('primaryInterval'),vaccinationText('boosterInterval'),vaccinationText('recurringInterval'),vaccinationText('product'),vaccinationText('status'),vaccinationText('edit')],rows)}</section>${settings&&vaccinationIsManager()?vaccinationScheduleForm():''}`;
}
